    const syncLabels={pending:'Pendente',running:'Executando',completed:'Concluída',partial:'Parcial',failed:'Falhou',awaiting_access:'Aguardando acesso autorizado',aguardando_verificacao_humana:'Aguardando verificação humana',not_started:'Não iniciada',not_implemented:'Não implementada'};
    async function loadSyncStatus(number=selected) { if(!number) return false; const data=await request(`/api/processes/${number}/sync`); const box=$('sync-status'); clear('sync-status'); box.hidden=false; box.append(node('strong',`Sincronização: ${syncLabels[data.status]||data.status}`)); const list=node('div',undefined,'sync-jobs'); for(const job of data.jobs) { const row=node('p',undefined,'muted'); row.append(node('strong',`${job.display_source||job.source}: ${syncLabels[job.status]||job.status}`)); if(job.message) row.append(document.createTextNode(` · ${job.message}`)); if(job.attempts) row.append(document.createTextNode(` · tentativa ${job.attempts}/${job.max_attempts}`)); if(job.counts) row.append(document.createTextNode(` · nesta tentativa: ${job.counts.movements_seen||0} movimentação(ões), ${job.counts.participants_seen||0} participante(s), ${job.counts.documents_seen||0} documento(s)`)); else if(job.records_seen) row.append(document.createTextNode(` · ${job.records_seen} registro(s) extraído(s)`)); if(job.records_available) row.append(document.createTextNode(` · já disponíveis: ${job.records_available.movements} movimentação(ões), ${job.records_available.participants} participante(s), ${job.records_available.documents} documento(s), ${job.records_available.hearings} audiência(s)`)); if(job.last_attempt_at) row.append(document.createTextNode(` · última tentativa em ${formatDate(job.last_attempt_at)}`)); if(job.last_successful_at) row.append(document.createTextNode(` · última coleta válida em ${formatDate(job.last_successful_at)}`)); if(job.next_attempt_at) row.append(document.createTextNode(` · próxima tentativa prevista em ${formatDate(job.next_attempt_at)}`)); if(job.coverage?.windows_completed!==undefined) row.append(document.createTextNode(` · ${job.coverage.windows_completed} janela(s), ${job.coverage.records_seen||0} comunicação(ões)`)); if(job.error?.message) row.append(document.createTextNode(` · ${job.error.message}`)); const protection=job.coverage?.protection; if(protection) { const labels={cloudflare_turnstile:'Cloudflare Turnstile',cloudflare_managed_challenge:'Desafio gerenciado Cloudflare',access_restricted:'Acesso restrito',portal_captcha:'CAPTCHA do portal',unknown_challenge:'Verificação não identificada',authentication_required:'Autenticação necessária'}; row.append(node('span',` · Proteção: ${labels[protection.type]||protection.type} · etapa: ${protection.stage} · observada em ${formatDate(protection.observed_at)} · sem repetição automática`)); row.append(details('Evidências técnicas da proteção',protection)); } list.append(row); } box.append(list); const verification=data.human_verification; if(verification?.status==='aguardando_verificacao_humana'||verification?.status==='queued') { box.append(node('p','A retomada abrirá uma nova janela local do navegador. Conclua o desafio no portal; a extração continua nessa sessão por até três minutos. Não feche a janela.','muted')); const cancel=node('button','Cancelar retomada','secondary'); cancel.type='button'; cancel.addEventListener('click',async()=>{ await request(`/api/processos/${number}/pje/retomada/${verification.id}/cancelar`,{method:'POST'}); await loadSyncStatus(number); }); box.append(cancel); } else if(verification?.status==='expired') { box.append(node('p','A janela expirou ou o worker reiniciou. Nenhuma consulta será repetida automaticamente; você pode iniciar uma nova retomada.','muted')); } else if(verification?.status==='cancelled') { box.append(node('p','A retomada assistida foi cancelada.','muted')); } if(data.jobs.some(job=>job.source.startsWith('TRF1-PJE')&&job.status==='awaiting_access')&&verification?.status!=='aguardando_verificacao_humana'&&verification?.status!=='queued') { const resume=node('button','Abrir consulta assistida no navegador'); resume.type='button'; resume.addEventListener('click',async()=>{ resume.disabled=true; try { await request(`/api/processos/${number}/pje/retomar`,{method:'POST'}); await loadSyncStatus(number); notice('Retomada solicitada. O worker local abrirá o navegador quando iniciar a coleta.'); } catch(error) { notice(error.message,true); } finally { resume.disabled=false; } }); box.append(resume); } const active=data.jobs.some(job=>['pending','running','aguardando_verificacao_humana'].includes(job.status)); syncWasActive=active; return active; }
    let currentGeneral=null,currentParticipants=[];
    function attributeText(general,key,value,fallback='Não informado pela fonte',forceConflict=false){
      const provenance=general?.proveniencia_atributos?.[key]||general?.attribute_provenance?.[key]||{};
      const conflict=forceConflict||provenance.conflict;
      if(!conflict)return value||fallback;
      const evidence=general?.conflitos_atributos?.[key]||provenance.conflict_evidence||provenance.decision_evidence||provenance.evidence||[];
      const visibleValue=item=>{let raw=item?.value;if(raw===null||raw===undefined||raw==='')return null;if(typeof raw==='boolean')return raw?'Sim':'Não';if(Array.isArray(raw))return raw.map(visibleValue).filter(Boolean).join(', ')||null;if(typeof raw==='object')return raw.nome||raw.name||raw.description||raw.descricao||raw.codigo||raw.code||null;return String(raw);};
      const values=[...new Set(evidence.map(item=>{const shown=visibleValue(item);return shown?`${item.source||'Fonte'}: ${shown}`:null;}).filter(Boolean))];
      if(values.length)return `${values.join(' · ')} (divergência entre fontes)`;
      return value||'Divergência entre fontes';
    }
