      const moveCard=card('Movimentações mais recentes','document');const moves=(events.items||[]).filter(x=>x.tipo==='movimentacao').sort((a,b)=>String(b.occurred_at||b.when||'').localeCompare(String(a.occurred_at||a.when||''))).slice(0,5);const moveList=node('div',undefined,'case-timeline-list');if(!moves.length)moveCard.append(node('p','Nenhuma movimentação disponível.','empty'));for(const event of moves){const row=node('article',undefined,'case-move');const context=`${event.titulo||event.title||''} ${event.complemento||event.description||''}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');const tone=/intim|publica|prazo/.test(context)?'orange':/peti|juntad|manifest|certidao/.test(context)?'red':/decis|sentenca|audiencia/.test(context)?'blue':'green';row.dataset.tone=tone;const glyph=/intim|publica/.test(context)?'bell':/prazo/.test(context)?'calendar':/decis|sentenca/.test(context)?'checkCircle':/peti|juntad|certidao/.test(context)?'document':'activity';const date=node('small',formatDate(event.occurred_at||event.when));const heading=node('div',undefined,'case-move-heading');const symbol=node('span',undefined,'case-move-symbol');symbol.append(icon(glyph));heading.append(symbol,node('strong',event.titulo||event.title||'Movimentação'));const sources=(event.fontes?.length?event.fontes:[event.fonte||event.source].filter(Boolean)).join(' · ');row.append(date,heading);if(sources)row.append(node('small',sources));if(event.complemento||event.description)row.append(node('p',event.complemento||event.description,'case-move-detail'));moveList.append(row);}if(moves.length)moveCard.append(moveList);const all=node('button',undefined,'case-link-button');all.type='button';all.append(node('span','Ver todas as movimentações'),icon('chevron'));all.addEventListener('click',()=>activate('movimentos'));moveCard.append(all);middle.append(moveCard);
