    function renderTimeline() {
      clear('timeline');
      const sourceSelect=$('movement-source'), previousSource=sourceSelect.value;
      const sourcesOf=item=>item.fontes?.length?item.fontes:[item.fonte].filter(Boolean);
      const availableSources=[...new Set(timeline.flatMap(sourcesOf))].sort();
      sourceSelect.replaceChildren(new Option('Todas',''),...availableSources.map(name=>new Option(name,name)));
      if(availableSources.includes(previousSource)) sourceSelect.value=previousSource;
      const start=$('movement-start').value,end=$('movement-end').value,source=sourceSelect.value,type=$('movement-type').value;
      const rows=timeline.filter(e=>(!start||e.occurred_at.slice(0,10)>=start)&&(!end||e.occurred_at.slice(0,10)<=end)&&(!source||sourcesOf(e).includes(source))&&(!type||e.tipo===type)&&(!$('movement-unread-only').checked||e.tipo!=='movimentacao'||e.is_unread));
      if(!rows.length) return empty('timeline','Nenhum evento disponível para este filtro.');
      for(const event of rows) {
        const entry=node('article',undefined,'entry');
        if(event.is_unread) { entry.classList.add('unread'); entry.append(node('span','Não lida','unread-badge')); }
        entry.dataset.eventId=event.id;
        entry.append(node('time',`${formatDate(event.occurred_at)} · ${event.temporal_context}`));
        const sourceNames=sourcesOf(event);
        const chosen={value:sourceNames.includes(event.preferred_source)?event.preferred_source:(sourceNames.includes('PJe/TRF1')?'PJe/TRF1':sourceNames[0])};
        const body=node('div',undefined,'source-version');
        if(sourceNames.length>1) {
          const switcher=node('div',undefined,'source-switch');
          switcher.setAttribute('role','group'); switcher.setAttribute('aria-label','Versão original da fonte');
          for(const sourceName of sourceNames) {
            const button=node('button',sourceName,'source source-badge'); button.type='button';
            button.setAttribute('aria-pressed',String(sourceName===chosen.value));
            button.setAttribute('aria-label',`Mostrar versão original de ${sourceName}`);
            button.addEventListener('click',()=>{ chosen.value=sourceName; for(const sibling of switcher.querySelectorAll('button')) sibling.setAttribute('aria-pressed',String(sibling===button)); renderSourceVersion(body,event,sourceName); });
            switcher.append(button);
          }
          entry.append(switcher);
        } else if(sourceNames.length) entry.append(node('span',sourceNames[0],'source'));
        entry.append(body);
        renderSourceVersion(body,event,chosen.value);
        if(event.tipo==='movimentacao') {
          entry.append(node('p',event.first_seen_at?`Identificada pelo ProcessWatch em ${formatDate(event.first_seen_at)}`:'Data de identificação desconhecida','muted'));
          if(event.is_unread) {
            const read=node('button','Marcar como lida','secondary'); read.type='button';
            read.addEventListener('click',async()=>{ read.disabled=true; try { const result=await request(`/api/processos/${selected}/eventos/${encodeURIComponent(event.id)}/ler`,{method:'POST'}); const idx=timeline.findIndex(item=>item.id===event.id); if(idx>=0) timeline[idx]=result.event; renderTimeline(); await loadPortfolio(); } catch(error) { notice(error.message,true); } finally { read.disabled=false; } });
            entry.append(read);
          }
        }
        $('timeline').append(entry);
      }
    }
    function renderSourceVersion(container,event,sourceName) {
      clearNode(container);
      const source=event.source_details?.find(item=>item.source===sourceName);
      const view=source?{...event,titulo:source.original_title||source.title||event.titulo,descricao:source.description,original_title:source.original_title,original_url:source.original_url,code:source.code,complements:source.complements||[],complement_display:source.complement_display||[],tpu:source.tpu,documents:source.documents||[],original:source.original}:event;
      const heading=node('h3',view.titulo); container.append(heading);
      if(view.descricao&&view.descricao!==view.titulo) container.append(node('p',view.descricao));
      if(view.code) container.append(node('p',`Código TPU: ${view.code} · nome original: ${view.original_title||'não informado'}`,'muted'));
      if(view.complement_display?.length) container.append(node('p',view.complement_display.map(x=>`${x.text} (${x.origin})`).join('; '),'muted'));
      if(view.complements?.length) container.append(details('Complementos desta fonte',view.complements));
      if(view.tpu?.complements?.length) container.append(details('Interpretação TPU',view.tpu.complements));
      if(event.equivalence) container.append(node('p','Evento consolidado; versões originais preservadas por fonte.','muted'));
      if(view.original) container.append(details(`Detalhes originais · ${sourceName||view.fonte}`,view.original));
      if(view.documents?.length) for(const doc of view.documents) {
        const box=node('p',`${doc.description||doc.label||doc.type||'Documento'} · ${doc.source||sourceName||'fonte'} · ${doc.link_status||'Link público não disponível'}`,'muted');
        if(doc.public_link_validated&&doc.url) { const link=node('a','Abrir documento no tribunal'); link.href=doc.url; link.target='_blank'; link.rel='noopener noreferrer'; box.append(document.createTextNode(' · '),link); }
        container.append(box);
      }
      if(view.original_url) { try { const url=new URL(view.original_url); if(url.protocol==='https:') { const link=node('a','Abrir fonte oficial'); link.href=url.href; link.target='_blank'; link.rel='noopener noreferrer'; container.append(link); } } catch {} }
    }
    function clearNode(element) { element.replaceChildren(); }
    function renderCommunications(data) { clear('panel-intimacoes'); $('panel-intimacoes').append(node('p',`DJEN: ${data.status}${data.period_start?` · período ${data.period_start} a ${data.period_end}`:''}${data.error?` · ${data.error}`:''}`,'muted')); if(!data.items?.length) return empty('panel-intimacoes',data.status==='período consultado'?'Nenhuma comunicação retornada pelo DJEN no período consultado.':'Não há comunicações confirmadas para exibir.'); for(const item of data.items) { const entry=node('article',undefined,'entry'); entry.append(node('time',`Disponibilização: ${formatDate(item.available_at)} · Publicação: ${formatDate(item.published_at)}`)); entry.append(node('h3',item.tipo||'Comunicação judicial')); entry.append(node('p',`${item.tribunal||'Tribunal não informado'} · ${item.orgao||'Órgão não informado'}`,'muted')); if(item.cancellation) entry.append(node('p',`Cancelamento: ${item.cancellation}`)); if(item.recipients?.length) entry.append(node('p',`Destinatários: ${item.recipients.join(', ')}`)); if(item.lawyers?.length) entry.append(node('p',`Advogados: ${item.lawyers.map(x=>`${x.nome} · OAB ${x.oab||'?'} ${x.uf||''}`).join('; ')}`)); if(item.text_plain) entry.append(node('p',item.text_plain)); if(item.text_original) entry.append(details('Ver texto original',item.text_original)); if(item.url) { try { const url=new URL(item.url); if(url.protocol==='https:') { const link=node('a','Abrir fonte'); link.href=url.href; link.target='_blank'; link.rel='noopener noreferrer'; entry.append(link); } } catch {} } $('panel-intimacoes').append(entry); } }
