    function renderDiscovery(data) {
      discoveryPage=data.page; discoveryTotal=data.total; clear('oab-results');
      const coverage=data.coverage;
      $('oab-coverage').textContent=`${data.total} processo(s) identificado(s) em ${data.publication_total??coverage?.matched??'?'} publicação(ões) do período ${data.period_start} a ${data.period_end} · ${coverage?.pages??'?'} página(s) consultada(s). Os resultados não representam todos os processos do advogado.`;
      if(!data.items.length) empty('oab-results',data.total?'Não há resultados nesta página.':'Nenhuma publicação encontrada no período consultado.');
      const groups=new Map();
      for(const item of data.items) { if(!groups.has(item.number)) groups.set(item.number,{formatted:item.formatted_number,monitored:item.monitored,communications:[]}); groups.get(item.number).communications.push(...(item.communications||[item.communication])); }
      for(const [number,group] of groups) {
        const card=node('article',undefined,'entry'), label=node('label',undefined,'pick'), checkbox=node('input'); checkbox.type='checkbox'; checkbox.checked=selectedDiscoveryNumbers.has(number); checkbox.setAttribute('aria-label',`Selecionar processo ${group.formatted}`); checkbox.addEventListener('change',()=>{ if(checkbox.checked) selectedDiscoveryNumbers.add(number); else selectedDiscoveryNumbers.delete(number); $('oab-add').disabled=!selectedDiscoveryNumbers.size; });
        label.append(checkbox,node('strong',group.formatted)); card.append(label,node('p',group.monitored?'Já monitorado; pode ser incluído em outra carteira.':'Descoberto em publicação DJEN.','muted'));
        for(const comm of group.communications) { const box=node('details'); box.append(node('summary',`${comm.tipo||'Comunicação'} · ${formatDate(comm.available_at)} · DJEN`),node('p',comm.text_plain||'Texto não disponibilizado nesta fonte.')); if(comm.url) { try { const url=new URL(comm.url); if(url.protocol==='https:') { const link=node('a','Abrir fonte oficial'); link.href=url.href; link.target='_blank'; link.rel='noopener noreferrer'; box.append(link); } } catch {} } card.append(box); }
        $('oab-results').append(card);
      }
      $('oab-pager').hidden=data.total<=data.size; $('oab-page-label').textContent=`Página ${data.page} de ${Math.max(1,Math.ceil(data.total/data.size))}`; $('oab-prev').disabled=data.page<=1; $('oab-next').disabled=data.page*data.size>=data.total;
      $('oab-add').disabled=!selectedDiscoveryNumbers.size;
    }
