    async function loadCredentials(){const data=await request('/api/service-credentials');const list=$('credential-list');list.replaceChildren();for(const item of data.items){const row=node('div',undefined,'entry');row.append(node('strong',item.name),node('small',`${item.active?'Ativa':item.revoked_at?'Revogada':'Expirada'} · Criada: ${formatDate(item.created_at)} · Validade: ${formatDate(item.expires_at)} · Último uso: ${item.last_used_at?formatDate(item.last_used_at):'Nunca'}`,'muted'),node('small',`Permissões: ${item.permissions.map(value=>credentialPermissionLabels[value]||value).join('; ')}`,'muted'));if(item.active){const actions=node('div',undefined,'actions');const rotate=node('button','Rotacionar','secondary');rotate.type='button';rotate.addEventListener('click',async()=>{if(!confirm(`Rotacionar a chave ${item.name}? A chave atual deixará de funcionar imediatamente.`))return;const days=Number($('credential-days').value);if(!Number.isInteger(days)||days<1||days>365)return notice('Informe uma validade entre 1 e 365 dias.',true);rotate.disabled=true;try{const result=await request(`/api/service-credentials/${item.id}/rotate`,{method:'POST',body:JSON.stringify({expires_in_days:days})});await loadCredentials();showCredentialSecret(result.token);notice('Chave rotacionada. Copie o novo segredo agora.');}catch(error){notice(error.message,true);}finally{rotate.disabled=false;}});const revoke=node('button','Revogar','secondary');revoke.type='button';revoke.addEventListener('click',async()=>{if(!confirm(`Revogar a chave ${item.name}? Esta ação invalida o acesso imediatamente.`))return;revoke.disabled=true;try{await request(`/api/service-credentials/${item.id}/revoke`,{method:'POST'});clearCredentialSecret();await loadCredentials();notice('Chave revogada.');}catch(error){notice(error.message,true);}finally{revoke.disabled=false;}});actions.append(rotate,revoke);row.append(actions);}list.append(row);}if(!data.items.length)list.append(node('p','Nenhuma chave de API cadastrada.','muted'));}
    $('credential-create').addEventListener('click',async()=>{const button=$('credential-create');const permissions=[...$('credential-permissions').querySelectorAll('input:checked')].map(input=>input.value),name=$('credential-name').value.trim(),days=Number($('credential-days').value);if(!name||!permissions.length||!Number.isInteger(days)||days<1||days>365)return notice('Informe nome, ao menos uma permissão e validade entre 1 e 365 dias.',true);button.disabled=true;try{const result=await request('/api/service-credentials',{method:'POST',body:JSON.stringify({name,permissions,expires_in_days:days})});$('credential-name').value='';await loadCredentials();showCredentialSecret(result.token);notice('Chave criada. Copie o segredo agora.');}catch(error){notice(error.message,true);}finally{button.disabled=false;}});
