    async function loadOabMonitors(){
      const root=$('oab-monitors-list');if(!root)return;root.replaceChildren();
      const response=await request('/api/monitoramentos/oab');
      if(!response.items?.length){root.append(node('p','Nenhuma OAB/UF em monitoramento recorrente.','empty'));return;}
      for(const monitor of response.items){
        const card=node('article',undefined,'entry'),head=node('div',undefined,'row-card');
        head.append(node('strong',`${monitor.lawyer_name?monitor.lawyer_name+' · ':''}OAB ${monitor.oab}/${monitor.uf}`),node('span',monitor.enabled?'Ativo':'Pausado','pill'+(monitor.enabled?'':' muted')));card.append(head);
        const latest=monitor.last_success_at?`Última consulta concluída: ${formatDate(monitor.last_success_at)}`:'Ainda sem consulta concluída';
        card.append(node('p',`${latest} · Próxima: ${monitor.next_run_at?formatDate(monitor.next_run_at):'sem agendamento'}`,'muted'));
        if(monitor.last_attempt_at)card.append(node('small','Última tentativa: '+formatDate(monitor.last_attempt_at),'muted'));
        if(monitor.last_error)card.append(node('p','Última falha: '+monitor.last_error,'status-note'));
        if(monitor.recent_jobs?.length){const last=monitor.recent_jobs[0];card.append(node('small',`Última execução: ${last.status==='queued'?'na fila':last.status==='running'?'em andamento':last.status==='completed'?'concluída':last.status==='failed'?'falhou':last.status}${last.window_start?' · janela '+last.window_start+' a '+last.window_end:''}`,'muted'));}
        const controls=node('div',undefined,'form-actions'),frequency=document.createElement('select');frequency.setAttribute('aria-label','Periodicidade da OAB '+monitor.oab);for(const hours of [6,12,24,48])frequency.append(new Option(`A cada ${hours} horas`,String(hours)));frequency.value=String(monitor.interval_hours);
        frequency.addEventListener('change',async()=>{try{await request(`/api/monitoramentos/oab/${monitor.id}`,{method:'PATCH',body:JSON.stringify({interval_hours:Number(frequency.value)})});await loadOabMonitors();notice('Periodicidade atualizada.');}catch(error){notice(error.message,true);}});
        const toggle=node('button',monitor.enabled?'Pausar':'Ativar','secondary');toggle.type='button';toggle.addEventListener('click',async()=>{toggle.disabled=true;try{await request(`/api/monitoramentos/oab/${monitor.id}`,{method:'PATCH',body:JSON.stringify({enabled:!monitor.enabled})});await loadOabMonitors();}catch(error){notice(error.message,true);toggle.disabled=false;}});
        const refresh=node('button','Atualizar agora','secondary');refresh.type='button';refresh.addEventListener('click',async()=>{refresh.disabled=true;try{const job=await request(`/api/monitoramentos/oab/${monitor.id}/atualizar`,{method:'POST'});notice(`Consulta enfileirada (execução ${job.job_id}).`);await loadOabMonitors();}catch(error){notice(error.message,true);}finally{refresh.disabled=false;}});
        const view=node('button','Ver publicações','secondary');view.type='button';view.addEventListener('click',()=>{communicationPreset={oab:monitor.oab,uf:monitor.uf};showView('communications');});
        const remove=node('button','Remover','secondary');remove.type='button';remove.addEventListener('click',async()=>{if(!window.confirm(`Remover o monitoramento da OAB ${monitor.oab}/${monitor.uf}? As comunicações já coletadas serão preservadas.`))return;try{await request(`/api/monitoramentos/oab/${monitor.id}`,{method:'DELETE'});await loadOabMonitors();notice('Monitoramento removido; publicações preservadas.');}catch(error){notice(error.message,true);}});
        controls.append(frequency,toggle,refresh,view,remove);card.append(controls);root.append(card);
      }
    }
